import { inject, provide } from 'vue';
import type { PlacementRef } from './placement.js';

// The root takes the placement, and the content reads it to position itself.
const key = Symbol('distill-tooltip');
export const provideTooltipPlacement = (placement: PlacementRef) => provide(key, placement);
export const injectTooltipPlacement = () => inject<PlacementRef>(key)!;

export { default as Root } from './Tooltip.vue';
export { default as Trigger } from './TooltipTrigger.vue';
export { default as Content } from './TooltipContent.vue';
export type { Placement } from './placement.js';

import type { Ref } from 'vue';

// Placement is written like Floating UI's ('bottom', 'top-start'…), the same as the
// Svelte version. Reka takes it as a side and an alignment, so this splits it.
export type Placement =
	'top' | 'right' | 'bottom' | 'left' | `${'top' | 'right' | 'bottom' | 'left'}-${'start' | 'end'}`;

export function toSideAlign(placement: Placement) {
	const [side, align = 'center'] = placement.split('-') as [
		'top' | 'right' | 'bottom' | 'left',
		('start' | 'end' | 'center')?
	];
	return { side, align };
}

export type PlacementRef = Readonly<Ref<Placement>>;
